<script module lang="ts">
/**
 * Filtered single choice (`design/components/combobox.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/combobox.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/combobox'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  agentMember,
  attributes,
  joinSlot,
  mergeParts,
  normalizeProps,
  useDirection,
  useMediaQuery,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/combobox.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import Skeleton from '../structure/Skeleton.svelte'

export type ComboboxFilter = NonNullable<ComboboxProps['filter']>

export interface ComboboxOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface ComboboxMessages {
  showOptions?: string
  clear?: string
  loadingOptions?: string
  options?: (count: number) => string
  list?: string
}

export interface ComboboxProps {
  /**
   * Keeps free text. Blur keeps the draft instead of restoring the selected label. A commit that
   * matches nothing sets the *selection* to `null` and keeps the text, which the app reads
   * through the controlled `inputValue` pair (React Aria's semantics, passed through). `name`
   * then serializes the typed text whenever no option is selected.
   */
  allowsCustomValue?: boolean
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Input's clear button. Clearing reports `onChange(null)`.
   */
  clearable?: boolean
  /**
   * Opens on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string | null
  disabled?: boolean
  /**
   * Apps localize by passing it. An empty dropdown shows one line of text, not an illustration.
   */
  emptyMessage?: string
  filter?: false | 'contains' | 'startsWith'
  id?: string
  /**
   * The controlled input text, which async apps use to drive their queries.
   */
  inputValue?: string
  invalid?: boolean
  /**
   * Async loading state: skeleton rows in the panel and a spinning glyph in the field.
   */
  loading?: boolean
  /**
   * The member's strings. See `ComboboxMessages`.
   */
  messages?: ComboboxMessages
  /**
   * Serializes the *selected value*, not the typed text.
   */
  name?: string
  /**
   * For touched validation. Fires after the blur has been resolved: free text that matched
   * nothing is already `null`, and the input shows the selected label again. So a check on leave
   * reads the resolved value, never the abandoned draft.
   */
  onBlur?: (event: FocusEvent) => void
  onChange?: (value: string | null) => void
  onInputChange?: (value: string) => void
  /**
   * Requests the next page. Fires when the highlight reaches the last row or the open listbox is
   * scrolled to its end, while `loading` is false, at most once per `options` length. The app
   * appends the next page and sets `loading`, and the skeleton rows appear below the existing
   * rows. The highlight trigger is the primary one (WCAG 2.1.1), because keyboard navigation
   * cannot reach a scroll edge when the page fits the panel.
   */
  onLoadMore?: () => void
  /**
   * The *current* list. In async use, the app supplies a new list for each query.
   */
  options: ComboboxOption[]
  placeholder?: string
  /**
   * `'auto'` shows the popup as a sheet below `30rem` (the conventions' sheet presentation).
   * `'popover'` keeps the popover at every width. There is no always-sheet value, because the
   * closed union does not allow one (`docs/layout.md`).
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * Selection only by default. Free text that matches nothing resolves to `null` on blur, and
   * the input restores the selected label. `allowsCustomValue` below is the explicit opt-in, not
   * a hidden mode of this pair.
   */
  value?: string | null
}
</script>

<script lang="ts">
let {
  allowsCustomValue = false,
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  clearable = false,
  defaultOpen,
  defaultValue,
  disabled = false,
  emptyMessage = 'No results',
  filter = 'contains',
  id: idOwn,
  inputValue,
  invalid: invalidOwn = false,
  loading = false,
  messages,
  name,
  onBlur,
  onChange,
  onInputChange,
  onLoadMore,
  options,
  placeholder,
  presentation = 'auto',
  size = 'md',
  value,
}: ComboboxProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
// svelte-ignore state_referenced_locally
let query = $state(options.find((option) => option.value === (value ?? defaultValue))?.label ?? '')
let showAll = $state(false)
let loadMoreAt = $state(-1)
let input = $state<HTMLElement | null>(null)
let list = $state<HTMLElement | null>(null)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
let sheetPanel = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const sheeting = $derived(presentation === 'auto' && phone.current)
const say = $derived({
  showOptions: 'Show options',
  clear: 'Clear',
  loadingOptions: 'Loading options…',
  options: (count: number) => (count === 1 ? '1 option' : `${count} options`),
  list: 'Suggestions',
  ...messages,
})
const collator = $derived(new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }))
const needle = $derived((inputValue ?? query).normalize('NFC'))
const matches = $derived((label: string) =>
  ((text: string) =>
    needle === '' ||
    (filter === 'startsWith'
      ? collator.compare(text.slice(0, needle.length), needle) === 0
      : Array.from({ length: Math.max(0, text.length - needle.length + 1) }, (_, at) =>
          text.slice(at, at + needle.length),
        ).some((part) => collator.compare(part, needle) === 0)))(label.normalize('NFC')),
)
const shown = $derived(
  filter === false || showAll ? options : options.filter((option) => matches(option.label)),
)
const lastEnabled = $derived(shown.findLast((option) => option.disabled !== true)?.value)
const requestMore = $derived(
  () =>
    !loading &&
    loadMoreAt !== options.length &&
    ((loadMoreAt = options.length), onLoadMore?.(), true),
)
const emitBlur = $derived((event: FocusEvent) => setTimeout(() => onBlur?.(event)))
const documentDirection = useDirection(() => input)
const service = useMachine(
  {
    ...zag.machine,
    implementations: {
      ...zag.machine.implementations,
      actions: {
        ...zag.machine.implementations?.actions,
        announceHighlightedItem: (params) =>
          zag.machine.implementations?.actions?.announceHighlightedItem?.({
            ...params,
            context: {
              ...params.context,
              get: ((name: string) =>
                name === 'value'
                  ? []
                  : params.context.get(name as never)) as typeof params.context.get,
            },
          }),
      },
    },
  } as typeof zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      collection: zag.collection({
        items: shown,
        itemToValue: (item) => item.value,
        itemToString: (item) => item.label,
        isItemDisabled: (item) => item.disabled === true,
      }),
      value: value === undefined ? undefined : value === null ? [] : [value],
      defaultValue: defaultValue == null ? undefined : [defaultValue],
      inputValue: inputValue,
      defaultOpen: defaultOpen,
      disabled: disabled,
      invalid: invalid,
      placeholder: placeholder,
      allowCustomValue: allowsCustomValue,
      inputBehavior: 'autohighlight' as const,
      positioning: { placement: 'bottom-start' as const, gutter: 2, sameWidth: false },
      ids: id === undefined ? undefined : { input: id },
      onPointerDownOutside: (event) =>
        panel?.contains(event.detail.originalEvent.target as Node) && event.preventDefault(),
      onValueChange: (details) => {
        onChange?.(details.value[0] ?? null)
      },
      onInputValueChange: (details) => {
        ;((query = details.inputValue),
          details.reason === 'input-change' && (showAll = false),
          onInputChange?.(details.inputValue))
      },
      onOpenChange: (details) => {
        ;((showAll =
          details.open && (details.reason === 'trigger-click' || details.reason === 'arrow-key')),
          !details.open && details.reason === 'escape-key' && revert())
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const revert = $derived(
  () =>
    (allowsCustomValue && api.value.length === 0) ||
    api.setInputValue(options.find((option) => option.value === api.value[0])?.label ?? ''),
)
const showClear = $derived(clearable && api.inputValue !== '' && !disabled)
const showEmpty = $derived(api.open && !loading && shown.length === 0)
const announcement = $derived(
  !api.open
    ? ''
    : loading
      ? say.loadingOptions
      : shown.length === 0
        ? emptyMessage
        : say.options(shown.length),
)
const formValue = $derived(api.value[0] ?? (allowsCustomValue ? api.inputValue : ''))
const present = usePresence(
  () => api.open && !sheeting,
  () => panel,
)
const sheetPresent = usePresence(
  () => api.open && sheeting,
  () => sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(
  () => api.open && sheeting,
  () => scrim,
  'dialog.scrim',
)
const effect1 = () => {
  api.open &&
    api.highlightedValue === null &&
    ((next) => next !== undefined && api.setHighlightValue(next))(
      api.value.find((chosen) => shown.some((option) => option.value === chosen)) ??
        shown.find((option) => option.disabled !== true)?.value,
    )
}
watchEffect(effect1, { watch: () => api.open })
const effect2 = () => {
  api.open && api.highlightedValue !== null && api.highlightedValue === lastEnabled && requestMore()
}
watchEffect(effect2, { watch: () => api.highlightedValue })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Combobox',
    element: () => input,
    state: () => ({
      value: api.value[0] ?? null,
      options: options.map((option) => ({
        id: option.value,
        label: option.label,
        ...(option.disabled === true ? { disabled: true } : {}),
      })),
      'input-value': api.inputValue,
      open: api.open,
      disabled: disabled,
      invalid: invalid,
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          (() => {
            if (api.value[0] === value) return
            api.setValue([value])
            api.setInputValue(options.find((option) => option.value === value)?.label ?? '')
          })(),
      },
      fill: { argument: 'text', run: (value) => api.setInputValue(value) },
      clear: () => (api.setValue([]), api.setInputValue('')),
      open: () => api.setOpen(true, 'trigger-click'),
      close: () => api.setOpen(false),
    },
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.field}
    id={api.getControlProps().id}
    data-size={size}
    data-state={api.open ? 'open' : 'closed'}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-loading={(loading) ? '' : undefined}
    data-sheeting={(sheeting && api.open) ? '' : undefined}
    data-member="combobox"
    ><input
      bind:this={input}
      {...attributes(mergeParts(api.getInputProps(), { onKeydown: (event: KeyboardEvent) => { if (event.key === 'Tab') api.open && api.highlightedValue !== null && api.selectValue(api.highlightedValue) }, onFocusout: (event: FocusEvent) => { emitBlur(event) } }))}
      class={styles.input}
      name={undefined}
      required={undefined}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={ariaDescribedby}
      aria-required={ariaRequired}
    />{#if name !== undefined
      }<input type="hidden" {name} value={formValue} disabled={disabled || undefined}
    />{/if
    }{#if showClear
      }<button
        class={styles.clear}
        type="button"
        aria-label={say.clear}
        onclick={() => { (api.clearValue(), api.focus()) }}
        ><Icon name="clear" {size}
      /></button
    >{/if
    }<button
      {...attributes(api.getTriggerProps())}
      class={styles.chevron}
      aria-label={say.showOptions}
      >{#if loading
        }<span class={styles.spinner}><Icon name="loading" {size} /></span
      >{:else
        }<Icon name="expand" {size}
      />{/if
    }</button
    ><div class={styles.status} role="status" aria-live="polite">{announcement}</div
  ></div
  ><Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          class={styles.content}
          style:--radix-popover-trigger-width={'var(--reference-width)'}
          style:--radix-popover-content-available-height={'var(--available-height)'}
          style:--radix-popover-content-transform-origin={'var(--transform-origin)'}
          data-size={size}
          data-state={api.open ? 'open' : 'closed'}
          data-member="combobox"
          ><ul
            bind:this={list}
            {...attributes(mergeParts(api.getContentProps(), { onScroll: () => { (list?.scrollHeight ?? 0) - (list?.scrollTop ?? 0) - (list?.clientHeight ?? 0) <= 32 && requestMore() } }))}
            class={styles.listbox}
            hidden={undefined}
            aria-label={say.list}
            aria-labelledby={ariaLabelledby === undefined ? undefined : `${api.getContentProps().id} ${ariaLabelledby}`}
            >{#each shown as option (option.value)
              }<li {...attributes(api.getItemProps({ item: option }))} class={styles.option}
                ><span class={styles.check}
                  >{#if api.value.includes(option.value)}<Icon name="confirm" size="sm" />{/if
                }</span
                ><span class={styles.text}
                  ><span class={styles.label}>{option.label}</span
                  >{#if option.description !== undefined
                    }<span class={styles.description}>{option.description}</span
                  >{/if
                }</span
              ></li
            >{/each
          }</ul
          >{#if loading
            }<div class={styles.rows} aria-hidden="true"
              >{#each [0, 1, 2] as row (row)
                }<div class={styles.row}><Skeleton textStep="sm" /></div
              >{/each
            }</div
          >{/if
          }{#if showEmpty}<div class={styles.empty} aria-hidden="true">{emptyMessage}</div>{/if
        }</div
      ></div
    >{/if
    }{#if scrimPresent.current
      }<div bind:this={scrim} class={sheet.scrim} data-state={api.open ? 'open' : 'closed'}></div
    >{/if
    }{#if sheetPresent.current
      }<div class={sheet.positioner}
        ><div
          bind:this={sheetPanel}
          class={sheet.panel}
          data-presentation="sheet"
          data-state={api.open ? 'open' : 'closed'}
          ><div bind:this={panel} class={styles.sheetBody} data-size={size} data-member="combobox"
            ><ul
              bind:this={list}
              {...attributes(mergeParts(api.getContentProps(), { onScroll: () => { (list?.scrollHeight ?? 0) - (list?.scrollTop ?? 0) - (list?.clientHeight ?? 0) <= 32 && requestMore() } }))}
              class={styles.listbox}
              hidden={undefined}
              aria-label={say.list}
              aria-labelledby={ariaLabelledby === undefined ? undefined : `${api.getContentProps().id} ${ariaLabelledby}`}
              >{#each shown as option (option.value)
                }<li {...attributes(api.getItemProps({ item: option }))} class={styles.option}
                  ><span class={styles.check}
                    >{#if api.value.includes(option.value)}<Icon name="confirm" size="sm" />{/if
                  }</span
                  ><span class={styles.text}
                    ><span class={styles.label}>{option.label}</span
                    >{#if option.description !== undefined
                      }<span class={styles.description}>{option.description}</span
                    >{/if
                  }</span
                ></li
              >{/each
            }</ul
            >{#if loading
              }<div class={styles.rows} aria-hidden="true"
                >{#each [0, 1, 2] as row (row)
                  }<div class={styles.row}><Skeleton textStep="sm" /></div
                >{/each
              }</div
            >{/if
            }{#if showEmpty}<div class={styles.empty} aria-hidden="true">{emptyMessage}</div>{/if
          }</div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
